export function nearestRoadNode(point){const c=point?.coordinate||point;if(!Array.isArray(c))throw Error('Expected [longitude,latitude]');let id,best=Infinity;const gx=Math.floor(c[0]/0.005),gy=Math.floor(c[1]/0.005),candidates=[];for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)candidates.push(...(curbGrid.get((gx+x)+','+(gy+y))||[]));for(const n of candidates.length?candidates:ROAD_GRAPH.pickupNodeIds||Object.keys(nodes)){const d=distanceM(c,nodes[n]);if(d<best){best=d;id=n;}}return {id,coordinate:nodes[id],distanceM:best,covered:best<=450,approximate:true};}
