function appendRoute(car,r,start,state){for(const e of r.edges){const s=segment(e,start,state);car.segments.push(s);start=s.endS;}return start;}
function roam(car,until){let tail=car.segments.at(-1),at=tail?.endS??(nowS-car.random()*20),node=tail?.toId??car.initialNode,prev=tail?.way||'';while(at<until){if(!insideBounds(nodes[node],roamingBounds)){car.segments.push({startS:at,endS:until,fromId:node,toId:node,state:'roaming',way:prev,waitingOutsideBounds:true});break;}let route;for(let attempt=0;attempt<30;attempt++){const local=zones[zoneOf(node)],pool=car.random()<0.25||!local.length?ids:local;const target=pool[Math.floor(car.random()*pool.length)];try{const candidate=routeRoad(node,target,prev,roamingBounds);if(candidate.durationS>20){route=candidate;break;}}catch{}}if(!route){car.segments.push({startS:at,endS:until,fromId:node,toId:node,state:'roaming',way:prev});break;}const delay=car.random()*12;if(delay>0){car.segments.push({startS:at,endS:at+delay,fromId:node,toId:node,state:'roaming',way:prev,destinationId:route.toId});at+=delay;}car.roamingTrips.push({fromId:node,toId:route.toId,startS:at,endS:at+route.durationS});at=appendRoute(car,route,at,'roaming');node=route.toId;prev=route.edges.at(-1).way;}}

for(let i=0;i<fleetSize;i++){const car={id:'DEMO-'+String(i+1).padStart(2,'0'),initialNode:(zones[i%4].length?zones[i%4]:ids)[Math.floor(random()*(zones[i%4].length||ids.length))],random:rng(seed+i*7919+1),segments:[],roamingTrips:[],reservation:null,revision:0,previousOrder:null};if(i%3!==0){let r;for(let attempt=0;attempt<20;attempt++){try{r=routeRoad(car.initialNode,(zones[i%4].length?zones[i%4]:ids)[Math.floor(random()*(zones[i%4].length||ids.length))],'',roamingBounds);if(r.durationS>60)break;}catch{r=null;const pool=zones[i%4].length?zones[i%4]:ids;car.initialNode=pool[Math.floor(random()*pool.length)];}}if(r&&r.durationS){const start=nowS-r.durationS*(0.15+random()*0.45);appendRoute(car,r,start,'existingorder');car.previousOrder={id:'PREVIOUS-'+car.id,route:r,startS:start,dropoffS:start+r.durationS,dropoffPoint:nodes[r.toId]};}}roam(car,nowS+300);cars.push(car);}
function prepareUntil(timeS){if(!Number.isFinite(timeS)||timeS<nowS)throw Error('Invalid preparation time');for(const car of cars){if(car.segments.at(-1).endS>timeS)continue;roam(car,timeS+600);const cutoff=timeS-1800;let keep=0;while(keep+1<car.segments.length&&car.segments[keep].endS<cutoff)keep++;if(keep)car.segments.splice(0,keep);car.roamingTrips=car.roamingTrips.filter(t=>t.endS>=cutoff);}}
