function offerQuotes({pickup=SCENE.pickup,passengerReadyS,destination=SCENE.destination,nowS:queryS=nowS,maxCandidates=12}){if(!Number.isFinite(passengerReadyS)||!Number.isFinite(queryS)||queryS<nowS)throw Error('Invalid quote time');prepareUntil(queryS);const pick=nodeId(pickup),dest=nodeId(destination),offers=[];const candidates=cars.filter(car=>!(car.reservation&&car.reservation.dropoffS>queryS)).map(car=>{const state=at(car,queryS),busy=state.state==='existingorder',available=busy?car.previousOrder.dropoffS:state.fromId===state.toId?queryS:state.endS,point=busy?car.previousOrder.dropoffPoint:nodes[state.toId];return {car,estimate:available+distanceM(point,nodes[pick])/12};}).sort((a,b)=>a.estimate-b.estimate||a.car.id.localeCompare(b.car.id)).slice(0,Math.max(1,Math.min(72,maxCandidates))).map(x=>x.car);for(const car of candidates){if(car.reservation&&car.reservation.dropoffS>queryS)continue;const current=at(car,queryS);let availableAtS=current.fromId===current.toId?queryS:current.endS,availableNode=current.toId,previousWay=current.way;if(current.state==='existingorder'){const orderEnd=car.segments.filter(s=>s.state==='existingorder').at(-1);availableAtS=orderEnd.endS;availableNode=orderEnd.toId;previousWay=orderEnd.way;}let deadheadRoute,passengerRoute;try{deadheadRoute=routeRoad(availableNode,pick,previousWay);passengerRoute=routeRoad(pick,dest,deadheadRoute.edges.at(-1)?.way||previousWay);}catch{continue;}const carArrivalS=availableAtS+deadheadRoute.durationS,pickupS=Math.max(passengerReadyS,carArrivalS);const q={id:'quote-'+(++quoteSeq),carId:car.id,revision:car.revision,quotedAtS:queryS,availableAtS,availableNode,availablePoint:nodes[availableNode],carArrivalS,passengerReadyS,pickupS,passengerWaitS:Math.max(0,carArrivalS-passengerReadyS),vehicleWaitS:Math.max(0,passengerReadyS-carArrivalS),dropoffS:pickupS+passengerRoute.durationS,deadheadRoute,passengerRoute,previousOrder:car.previousOrder,currentState:current.state};quotes.set(q.id,q);if(quotes.size>384)quotes.delete(quotes.keys().next().value);offers.push(q);}return offers.sort((a,b)=>a.dropoffS-b.dropoffS||a.deadheadRoute.durationS-b.deadheadRoute.durationS||a.carId.localeCompare(b.carId));}
function reserveQuote(id){const q=quotes.get(typeof id==='string'?id:id?.id);if(!q)throw Error('Unknown quote');const car=cars.find(c=>c.id===q.carId);if(car.revision!==q.revision||(car.reservation&&car.reservation.dropoffS>q.quotedAtS))throw Error('Vehicle already reserved; refresh quotes');car.segments=car.segments.filter(s=>s.startS<q.availableAtS).map(s=>s.endS<=q.availableAtS+1e-7?s:{...s,endS:q.availableAtS});car.roamingTrips=car.roamingTrips.filter(t=>t.endS<=q.availableAtS+1e-7);appendRoute(car,q.deadheadRoute,q.availableAtS,'pickup');if(q.pickupS>q.carArrivalS)car.segments.push({startS:q.carArrivalS,endS:q.pickupS,fromId:q.passengerRoute.fromId,toId:q.passengerRoute.fromId,state:'pickup'});appendRoute(car,q.passengerRoute,q.pickupS,'passengertrip');car.reservation={...q};car.revision++;roam(car,q.dropoffS+900);return {...q};}
